security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['configureAssets']['enabled']: 
		canCreate = True if value['attribute']['attributeId'] else False
		canEdit = True if value['attribute']['attributeAssetLinkId'] else False

return {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}


if value is None: return False
try:
	return value.rowCount > self.props.pager.initialOption
except:
	return False

customMethods.script:

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
attrAssetInfo = dict(self.view.custom.dataSource.info)

if attrAssetInfo['attributeAssetLinkId'] is None:
	attributeDataSourceId, msg = system.kanoa.attribute.addAttributeAssetLink(attrAssetInfo, userId)
	if msg is None: 
		self.view.custom.dataSource.info.attrAssetInfo = attrAssetInfo
		system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute link has been added"})		
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})		
else:
	retVal, msg = system.kanoa.attribute.updateAttributeAssetLink(attrAssetInfo, userId)
	if msg is None:	system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute asset link has been updated"})		
	else: system.perspective.sendMessage('showFailerToast', {'message': msg})				

self.view.refreshBinding("custom.dataSource.table.data")
self.view.custom.dataSource.create = False

return

userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)
for row in self.view.custom.dataSource.table.selection.data:
	retVal, msg = system.kanoa.attribute.deleteAttributeAssetLink(row['attributeAssetLinkId'], userId)
	if retVal: system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute asset link has been deleted"})	
	else: system.perspective.openPopup('msg', 'kanoa/core/templates/displays/messagePopup', params = {'text':msg}, showCloseIcon=True, draggable=True, resizeable=True)

self.view.refreshBinding("custom.dataSource.table.data")	

return

